import os, json, pickle
from pathlib import Path
import numpy as np
base = Path('/app/data')
print('DATA SUMMARY')
for path in sorted(base.rglob('*')):
    if path.is_dir():
        continue
    rel = path.relative_to(base)
    suf = path.suffix.lower()
    size = path.stat().st_size
    print(f'FILE\t{rel}\t{size} bytes')
    try:
        if suf == '.npy':
            arr = np.load(path, allow_pickle=True)
            if isinstance(arr, np.ndarray):
                print('  NPY', 'dtype=', arr.dtype, 'shape=', arr.shape)
                if arr.dtype == object and arr.shape == ():
                    obj = arr.item()
                    print('  NPY-ITEM type=', type(obj), 'keys=', list(obj.keys())[:20] if isinstance(obj, dict) else 'NA')
            else:
                print('  NPY type=', type(arr))
        elif suf == '.npz':
            z = np.load(path, allow_pickle=True)
            print('  NPZ keys=', list(z.keys()))
            for k in list(z.keys())[:10]:
                v = z[k]
                print('   ', k, getattr(v, 'shape', None), getattr(v, 'dtype', None))
        elif suf == '.pkl':
            with open(path, 'rb') as f:
                obj = pickle.load(f)
            print('  PKL type=', type(obj))
            if isinstance(obj, dict):
                print('  PKL keys=', list(obj.keys())[:20])
        elif suf == '.json':
            with open(path) as f:
                obj = json.load(f)
            print('  JSON type=', type(obj), 'keys=', list(obj.keys())[:20] if isinstance(obj, dict) else 'NA')
        elif suf in ['.csv', '.tsv']:
            with open(path) as f:
                for i in range(3):
                    line = f.readline()
                    if not line:
                        break
                    print('  ', line.rstrip())
        elif suf in ['.mat']:
            print('  MAT file (not yet inspected)')
    except Exception as e:
        print('  INSPECT ERROR', repr(e))
